# The revamp's outline: builders -> new slides (id, chapter, working title, the point, the old slides it replaces, notes)
B = {}
def b(code, name, file, slides, extra=''): B[code] = dict(name=name, file=file, slides=slides, extra=extra)
b('r1', 'The intro: every flagship compromises', '30-r1-intro.js', [
 ('r1_cover','intro','Theseus: zero compromises','The promise in one frame: the lightest flagship-class mouse that gives up nothing. PIAKNOW\'S in capitals; "zero compromises" where 8 khz was; density where "100+ ideas" was.',['cover']),
 ('r1_compromise','intro','Every flagship compromises','The problem that the whole film answers: each flagship trades something away (battery for weight, durability for weight, an optical switch\'s battery for speed, shape for weight, price). A table or map of named flagships, each with its own sourced compromise, and Theseus with none. Derive every blank; one precision per column; the Superstrike X3 is a flagship (the GPX 2 less so).',['flagships','thesis','market']),
 ('r1_targets','intro','The targets','What zero compromises means in numbers: Dual 8khz wired and wireless, press to PC (shorter: the click work cuts mechanical latency), weight headlined against the Starlight X; set-down and idle sleep left out this early.',['targets','targets2']),
 ('r1_zero','intro','Why lighter wins','The reason weight matters, argued properly: theoretical ease of control and how fast you can change targets (less mass, less force to start and stop), not "overall speed". Teach it with a classroom demonstration (F = ma: a cart, a shopping trolley, a wrist flick).',['zerograms']),
 ('r1_listed','intro','Listed against weighed','The problem of misadvertised weights: brands list one weight and ship another. Carry the thesis\'s message ("optimization over opinion") here, as he asked.',['weightgap']),
 ('r1_density','intro','Density, not weight','The X2F\'s wrong idea first (the problem), then density as the fix: the size-weight illusion, why a low-density mouse feels lighter in the hand. Only outlines or silhouettes of the mice, never detailed drawings.',['ntr_density','ntr_sizewt']),
 ('r1_rank','intro','Ranked by density','Honest ranking among wireless mice: G-Wolves from EloShapes included even where Theseus looks worse; the X2F CrazyLight at its best-reported weight (at least 29.5 g); one precision for every mouse; the XA25 shown but not ranked (wired).',['ntr_densrank']),
 ('r1_price','intro','Price against weight','A Pareto front that never kinks (it continues its trajectory), with the Viper Mini Signature Edition, the Zaunkoenig mice and the Superstrike X3 added.',['pricefront']),
 ('r1_budget','intro','Where 29.31 g goes','The weight budget, computed from the deck\'s own data so it updates itself (his note: "a lot of work to keep updating this one"); the facts from ntr_stats that belong here.',['budget','ntr_stats']),
 ('r1_close','end','Zero compromises','The close: each compromise from r1_compromise, answered, in one frame.',['close']),
], extra="You own the intro's data: research is most of your work (EloShapes, reviews, maker pages), and every number is sourced or derived and marked.")
b('r2', 'Clicks I: the mechanics that matter most', '30-r2-click.js', [
 ('r2_card','click','Clicks that land the same, every time','The chapter card, framed as the problem most mice have (a click that changes with where and how you press).',['clicks']),
 ('r2_cutouts','click','Straight rear cutouts','Among his most important ideas, and the worst executed: show the whole mouse first, then the zoom, so the viewer knows where they are; the rival\'s angled cutout (Viper V2 Pro against the V3 Pro) and what it does to the press; Theseus\'s straight, centred cutout; what the player feels.',['cutouts']),
 ('r2_seams','click','Seams that keep your fingers out','From his shell sheet note: the further a seam sits from the centre, the easier it catches your fingers; where Theseus puts its seams, and why.',['shlsheet1']),
 ('r2_front','click','A flat front: no wobble','His clk_front note, left half: a front with heavy comfort grooves never bottoms out in the same spot, so it wobbles side to side, feels cheap and wears faster; Theseus\'s flat front; it locks the fingers in another plane and adds contact area. Not cross-sections for the grooves.',['clk_front']),
 ('r2_flush','click','Flush walls, small gaps','His clk_front note, right half: how some mice make the gaps bigger than they should be, and how Theseus does it right; a chance to show why the cutouts face the ceiling or the wall.',[]),
 ('r2_direct','click','Direct Drive Actuation','The switch turned 20° onto the trigger\'s arc (K1\'s slide, v22): rival first (a flat switch scraping its guide), then the fix; keep "6% sooner" with why it isn\'t 20%; no pts.',['arc']),
 ('r2_wedge','click','One flat board, fewer parts','The problem with more parts first (tilted sub-boards, wedges, tolerances stacking), then the one flat board; "important concept, very poor execution".',['clk_wedge']),
 ('r2_tension','click','The bridge tensioner','K1\'s tensioner and its material tiles (v22) made one dense slide or two: the stiff composite plane "as seen in Starlight X" against the bridge; no fillets where the bridge meets the trigger; what the player feels (crisp and light).',['tensioner','clk_tenmat']),
 ('r2_rails','click','Two equal posts, on POM pads','K1\'s anchors (v22) with clk_pomtune folded in: one plane of motion explained plainly; uniform posts and pads; the cheap feel and wear of the one-post version; POM pad thickness setting the tolerance, against another mouse\'s tolerances.',['anchors','clk_pomtune']),
], extra="K1 rebuilt several of these slides for v22 (deck/src/10-b-click.js): reuse its drawings and numbers (copy what you need into your file), and re-frame them problem-first. Brock's tensioner photos: /mnt/user-data/attachments/17d0b892-9041-5973-afc8-9659df39052b/0300b3c2-image.jpg, c82f85d5-image.jpg, 1fce7c7f-image.png.")
b('r3', 'Clicks II and Glide', '30-r3-clickglide.js', [
 ('r3_switch','click','A mechanical switch, binned honestly','K1\'s clk_switch (v22) with clk_switch2 folded in as provable binning (companies lie about their binning; Theseus commits to bins it can prove, possibly with Hall-effect testing, said as a proposal); Razer staff\'s "almost half the battery" as a claim (Razer staff online, per Brock).',['clk_switch','clk_switch2']),
 ('r3_hotswap','click','Swap a switch in a minute','Why it matters first (a double-clicking switch ends a mouse); the claw clips clearly visible; no solder.',['clk_hotswap']),
 ('r3_timing','click','Counted at first contact','One simple slide for the click timing (G10): counted at the first contact of an SPDT switch, never waiting for motion, every number with its method.',['latency','clk_spdt','clk_wait','clk_methods']),
 ('r3_debounce','click','Debounce: low, and yours to set','Low debounce is good for most players; some (Minecraft players) want it longer to count more double clicks: low by default, adjustable.',['clk_debounce']),
 ('r3_side','click','Dual rail side buttons','K1\'s sidebuttons (v22): the same post as the main buttons on POM pads, a fixed guide over a full-size switch (he wanted to see it before deciding); the rival\'s lazy hinge-on-a-mini-switch made accurate.',['sidebuttons']),
 ('r3_gcard','glide','Aim that goes where you put it','The glide chapter card, as the problem.',['glide']),
 ('r3_skates','glide','Skates where they count','The Viper V4-style big skates against targeted dots: more area where it reduces sink, less weight; the corner-dot ledges as long as the sensor skate ledge (room for 3 skates), no gap to the shell, filleted where the skate meets it; dots beside the lens at ±11.5 mm with the plate off.',['gld_under','dots','gld_sag']),
 ('r3_sees','glide','How a sensor sees','One slide for camera, correlation and defocus, drawn like the rest of the deck (no photo-real pad).',['gld_camera','gld_corr','gld_blur']),
 ('r3_focus','glide','A focus window of 0.2 mm','Keep what works; tie it to the lift-off the player sets (the lift-off setting itself is on the software slide).',['focus']),
 ('r3_module','glide','Snap-on lens: one dot wide','He liked this one (8/10): keep it, re-framed problem-first.',['gld_module']),
 ('r3_sensor','glide','The PAW3970','The suspected sensor in the Viper V4 Pro, and the plan once its exclusivity ends; full 16-bit reports explained as a demonstration, not a graphic; the three details from gld_sheet folded in where they belong.',['sensor','gld_reports','gld_sheet']),
], extra="K1's v22 slides (clk_switch, sidebuttons) are in deck/src/10-b-click.js: reuse them. Note: the sensor moves forward on the new board (K2): don't draw lens positions from the old board; ask main for the new numbers if you need them.")
b('r4', 'Shell I: materials and strength', '30-r4-shell.js', [
 ('r4_card','shell','Light, without the flex, creak or crack','The shell chapter card, as the problem.',['shellcard']),
 ('r4_material','shell','Carbon-filled polypropylene','ABS against PP-C-20A, stated as a flat test, with the force scaled to a hand on a mouse and said on the slide; the projected weights of both beams; specific strength and stiffness explained so a viewer sees why higher is better (a classroom demonstration).',['materials','shlSpecific']),
 ('r4_wall','shell','How thin a wall can go','"super important concept": the minimum wall thickness and the tolerance cubed, at a glance; no pts.',['thinwall','shlScatter']),
 ('r4_fallacy','shell','The strength-weight fallacy','The GPX 2 is heavier than the ULX and built worse: that is the fallacy; axes that read at a glance (y as strength, not flex); never call the GPX 2\'s build quality good.',['shlPick']),
 ('r4_nopick','shell','What if you didn\'t have to pick','The header on the first frame (his G9 complaint); Theseus\'s method as its own line; the comparisons of the last slide; no strength graphs carried across slides.',['shlNoPick','shlShell3d']),
 ('r4_hotspot','shell','Where a shell breaks','Stress hotspots and the peak that decides the break, with the weight of both parts shown, so a milled-out part stronger than a solid one is pointed out.',['shlHotspot','shlMargin']),
 ('r4_work','shell','Putting the weight to work','The example behind many design choices: say so, and give it room for more information.',['shlWork']),
 ('r4_lattice','shell','Triangles, not hexagons','Human force on the mouse, said; hexagons bending a lot more; statically determinate triangles taught with a classroom demonstration (a square of straws sags, a triangle holds).',['lattice','shlDeterminate']),
 ('r4_light','shell','Triangles win more on a light mouse','The fact he loves, made compelling: max load to bend as the mouse gets lighter.',['shlThin']),
], extra="Cut the strength meter that ran across several slides (his note on shlShell3d). The FE numbers come from 07-sim.js and the shell data in 10-d-shell.js: reuse them.")
b('r5', 'Shell II: arches, fillets, the board, the build', '30-r5-shell.js', [
 ('r5_arches','shell','Arches, interwoven','Arches on the rim, without wobbly lines; arch action against a flat plate with real-world arches (a Roman arch, an eggshell) for a social-media viewer.',['shbArches','shbPress']),
 ('r5_thrust','shell','How an arch carries a press','The thrust line, thrust cancelling bending, and fibres along the load in one slide, taught with classroom demonstrations (a hanging chain flipped upright, as in Gaudi\'s models; wood splitting along its grain).',['shbThrust','shbBend','shbFibres']),
 ('r5_fillet','shell','A fillet at every node','Why corners get fillets (the Comet airliner\'s square windows), and the fillet size solved at equal mass (filletsize was 10/10: keep its content); no shell study shown here.',['fillet','filletsize']),
 ('r5_filletplus','shell','What a fillet also buys','Fibre flow through a node, one rib width, a mould easier to cut (no knife edges of steel), a looser tolerance: one dense slide.',['shbFlow','shbWidth','shbMill','shbMillDirect','shbTol']),
 ('r5_board','shell','The board you already carry','FR4 is a woven composite like carbon fibre, so the board can be the stiffener instead of carbon rods, with no extra parts or tolerances; G-Wolves\' small arms (his photos; they broke in shipping) against the whole board.',['shlPcbRib','shcCarry','shcArms']),
 ('r5_tested','shell','A published deflection test','The spec explained so a viewer knows what it means (not a big blue number with no setup).',['shlStructs']),
 ('r5_tolerance','shell','Tolerance stack-up','The law behind it (tolerance stack-up, sourced), simplified mouse parts for the drops, a classroom demonstration (stacked coins), no Theseus teardown; one bad part ruins the whole mouse.',['tolerance']),
 ('r5_mass','shell','Where the mass sits','Research why some people push for a higher battery placement, sourced, and show both sides honestly; the balance stays at the mouse\'s centre (his decision).',['mass']),
 ('r5_poron','shell','Poron pads, not grease','Factory Poron pads where the board meets the shell: players already mod G-Wolves mice this way to stop creaking.',['grind']),
 ('r5_sheet','shell','The rest of the shell','The shell\'s remaining ideas in one sheet: PPS triggers, the film sticker (he is unsure: say so or drop it), a closed wheel well, an optional base, graded walls, joined struts; no pro model.',['shlsheet2']),
], extra="Brock's G-Wolves photos: /mnt/user-data/attachments/17d0b892-9041-5973-afc8-9659df39052b/d2ae72fe-image.png and 80f31ed6-image.jpg. The plate slides stay out (\"we will worry about the bottom cover later\").")
b('r6', 'Surface, shape and ownership', '30-r6-surface.js', [
 ('r6_scard','surface','Grip that holds, and stays','The surface chapter card: the surfaces must look good in 2D and 3D (his note).',['surfacecard']),
 ('r6_coating','surface','A baked ceramic coat','Flames and realistic pots for the bake, not lazy icons; 9H "on Cerakote\'s tests"; UV and chemical resistance folded in.',['coating','srf_uv']),
 ('r6_film','surface','A film too thin to weigh','The height before sanding and coating; Cerakote\'s film weight checked (0.49 g looks far too heavy for a film thinner than soft touch); the soft-touch comparison he liked.',['srf_texture','srf_weight']),
 ('r6_grip','surface','Directional grip, no tape','Really good, made more intuitive; "the best thickness is no thickness": players chase thinner grip tape, this has none.',['grip','srf_tape']),
 ('r6_gripmap','surface','A grip map for the hand','Grip designs optimized to look good, blending between textures; two-tone folded in ("not a universal part of the design, but i love how realistic it is").',['srf_gripmap','srf_twotone']),
 ('r6_wheel','surface','A 0.9 g magnesium wheel','Against average plastic wheels with heavy rubber, a test group, sourced; the straight knurl (back from the diamond).',['wheel']),
 ('r6_shcard','shape','A shape measured on hands','The shape chapter card, as the problem.',['shapecard']),
 ('r6_newton','shape','Newtonian shape analysis','Keep, re-framed problem-first.',['shp_newton']),
 ('r6_grooves','shape','Comfort grooves that fade to the front','Keep, tied to the flat front (r2_front).',['grooves']),
 ('r6_size','shape','Sized on real hands','Size and EMG on every revision in one slide.',['size','emg']),
 ('r6_sides','shape','Flat low sides','Equal pressure on both sides, just for show; the asymmetry looked bad; in the Shape chapter now.',['shbSides']),
 ('r6_ocard','own','Made to last, and to open','The ownership chapter card, as the problem.',['owncard']),
 ('r6_repair','own','Made to be opened','Repairability with the board and the side-entry battery plug.',['repair','ownboard','ownbatt']),
 ('r6_screws','own','Screws that never strip','M2 titanium combination-drive screws, brass heat-set inserts, thread wear: one dense slide (the titanium claims as sourced in v22).',['ownscrew','own_insert','own_life']),
 ('r6_box','own','In the box','The trifold box and driver, and the ideas from both ownership sheets that belong nowhere else (ownsheet1 "feels redundant, most of this should be moved to other slides": move each point to its slide, keep the rest here).',['box','ownsheet1','ownsheet2']),
], extra="Use the board's shared drawing helpers for any board (K2 is redrawing the board; your slides pick it up when it lands).")
b('r7', 'Electronics: wireless with no penalty', '30-r7-elec.js', [
 ('r7_card','elec','Wireless with no penalty','The electronics chapter card, as the problem.',['eleccard']),
 ('r7_chip','elec','One chip, one radio, the antenna clear','Single-chip 8 khz, the Raytac module (AN54LM-P20A, long antenna) and the antenna turned away from the wheel, in one or two slides.',['onechip','elc_module','antenna']),
 ('r7_latency','elec','Motion latency, simply','Simple (G10): ranked motion latency and the wireless penalty, at a glance.',['motion','elc_rate']),
 ('r7_sync','elec','Frame sync and a spare report','Simple: 202 -> 42 us frame to USB (Viper V4 Pro; the XA25 with SensorLock on a PAW3950), and Second Shot.',['framesync','secondshot']),
 ('r7_battery','elec','Battery life with nothing given up','Battery life against polling rate and the Pareto frontier, the zero-compromise case.',['power','frontier']),
 ('r7_cells','elec','The battery, per gram','K2\'s fix: small cells (a 10440, 350 mAh, 9 g), Li-ion a gram or two heavier than Li-po of the same capacity.',['cells']),
 ('r7_power','elec','One chip runs the power','The PMIC, fast charging at the battery\'s 1C and the four guards; the PMIC sits far from the MCU on the new board (K2).',['elc_pmic','elc_charge','elc_safe']),
 ('r7_nolight','elec','Nothing lights up but the sensor','K2\'s slide (srf_encoder, now in Electronics after software): magnetic encoder, mechanical switches, no RGB LED, each with its battery figure.',['srf_encoder','elc_sheet2']),
 ('r7_board','elec','One board, one side, sealed','One reflow on one side, better visualized, and the conformal coat that keeps water out for very little weight.',['elc_oneside','elecsheet1']),
 ('r7_wires','elec','Wires that last','Braided, twisted, laid and flexed: one dense slide.',['elc_tear','elc_twist','elc_lay','elc_flex']),
 ('r7_cable','elec','An angled plug, a paracord cable','K2\'s new cable slide: woven paracord, the angled plug on the shell.',['cable']),
 ('r7_software','elec','Set it once, in the browser','Web software with nothing to install, and the lift-off distance set in 0.1 mm steps, sold properly (from gld_soft).',['software','gld_soft']),
], extra="K2 improved cells, elecsheet1, cable and srf_encoder (they are in HEAD): reuse them. The new board (K2) will move the PMIC and swap the sensor and MCU: use the shared board helpers so your slides follow it.")
